package org.humanjourney.core.geography.map;
import java.util.*;
import org.humanjourney.core.geography.*;
/** Discovered-only client BVH over individual components, sharing server indexing primitives. */
public final class MapSpatialIndex {
 private final Map<MapArea.Key,MapArea> areas;private final AreaSpatialIndex<MapArea> index;
 public record Hover(String local,String macro,int candidates,boolean ambiguous,MapArea localArea,MapArea macroArea,int localComponent,int macroComponent){public Hover(String l,String m,int c,boolean a){this(l,m,c,a,null,null,-1,-1);}public Hover(String l,String m,int c,boolean a,MapArea la,MapArea ma){this(l,m,c,a,la,ma,la==null?-1:0,ma==null?-1:0);}public MapArea.Key localKey(){return localArea==null?null:localArea.key();}public MapArea.Key macroKey(){return macroArea==null?null:macroArea.key();}public boolean visible(){return !local.isEmpty()||!macro.isEmpty();}public String primary(){return local.isEmpty()?macro:local;}public String secondary(){return local.isEmpty()?"":macro;}}
 public MapArea area(MapArea.Key key){return areas.get(key);}
 public MapSpatialIndex(Map<MapArea.Key,MapArea> areas){this.areas=Map.copyOf(areas);GeographyGeometry.catalog(areas.values().stream().map(MapArea::shape).toList());var entries=new ArrayList<AreaSpatialIndex.Entry<MapArea>>();for(var a:areas.values())for(int i=0;i<a.shape().parts().size();i++)entries.add(new AreaSpatialIndex.Entry<>(a,a.dimension(),a.kind().name(),i,a.shape().parts().get(i)));index=new AreaSpatialIndex<>(entries);}
 public List<AreaSpatialIndex.Entry<MapArea>> queryParts(String dimension,MapArea.Kind kind,MapArea.Bounds box){return index.query(dimension,kind.name(),box);}
 public List<MapArea> query(String dimension,MapArea.Kind kind,MapArea.Bounds bounds){var result=new TreeMap<MapArea.Key,MapArea>();for(var e:queryParts(dimension,kind,bounds))result.put(e.area().key(),e.area());return new ArrayList<>(result.values());}
 private record Hit(MapArea area,int component){}
 private static Hit best(List<AreaSpatialIndex.Entry<MapArea>> candidates,double x,double z){var matches=new TreeMap<MapArea.Key,Hit>();for(var e:candidates)if(e.contains(x,z))matches.merge(e.area().key(),new Hit(e.area(),e.component()),(a,b)->a.component()<b.component()?a:b);Hit best=null;boolean tie=false;for(var h:matches.values())if(best==null||h.area().priority()>best.area().priority()){best=h;tie=false;}else if(h.area().priority()==best.area().priority())tie=true;if(tie)throw new IllegalArgumentException("ambiguous discovered map geography");return best;}
 public Hover hover(String dimension,double x,double z){if(!Double.isFinite(x)||!Double.isFinite(z)||Math.abs(x)>30000000||Math.abs(z)>30000000)return new Hover("","",0,false);var box=new MapArea.Bounds(x,z,x,z);var locals=queryParts(dimension,MapArea.Kind.LOCAL,box);var macros=queryParts(dimension,MapArea.Kind.MACRO,box);Hit local=null,macro=null;boolean ambiguous=false;try{local=best(locals,x,z);}catch(IllegalArgumentException e){ambiguous=true;}if(local!=null&&!local.area().parent().isEmpty()){var parent=areas.get(new MapArea.Key(MapArea.Kind.MACRO,local.area().parent()));if(parent!=null&&parent.dimension().equals(dimension)){int component=-1;for(var e:macros)if(e.area().key().equals(parent.key())&&e.contains(x,z)&&(component<0||e.component()<component))component=e.component();macro=new Hit(parent,component);}}if(macro==null)try{macro=best(macros,x,z);}catch(IllegalArgumentException e){ambiguous=true;}return new Hover(local==null?"":local.area().label(),macro==null?"":macro.area().label(),locals.size()+macros.size(),ambiguous,local==null?null:local.area(),macro==null?null:macro.area(),local==null?-1:local.component(),macro==null?-1:macro.component());}
}
